#include <windows.h>
#include <stdio.h>

int main(void)
{
    DWORD before = GetTickCount();
    Sleep(3000); // 3초 대기 - 샌드박스 타임아웃 회피 또는 타이밍 체크 기준점
    DWORD after = GetTickCount();

    if (after - before < 2900) {
        printf("Sleep was patched/hooked - debugger suspected\n");
    }
    return 0;
}

