#include <windows.h>
#include <stdio.h>

typedef LONG (NTAPI *pNtQueryInformationProcess)(
    HANDLE ProcessHandle, DWORD ProcessInformationClass,
    PVOID ProcessInformation, ULONG ProcessInformationLength, PULONG ReturnLength);

int main(void)
{
    HMODULE hNtdll = GetModuleHandleA("ntdll.dll");
    pNtQueryInformationProcess NtQIP =
        (pNtQueryInformationProcess)GetProcAddress(hNtdll, "NtQueryInformationProcess");

    DWORD_PTR debugPort = 0;
    NtQIP(GetCurrentProcess(), 7 /* ProcessDebugPort */, &debugPort, sizeof(debugPort), NULL);

    if (debugPort != 0) {
        printf("Debugger detected via ProcessDebugPort\n");
    }
    return 0;
}
